1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	import org.springframework.samples.petclinic.util.E164PhoneNumbers;
12	
13	import java.time.LocalDate;
14	import java.time.Period;
15	import java.util.Collection;
16	import java.util.List;
17	import java.util.Map;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName",
26	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
27	    @Mapping(target = "initials",
28	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" "
29	            + "+ owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
30	    @Mapping(target = "membershipLevel",
31	        expression = "java(toMembershipLevel(owner))")
32	    @Mapping(target = "locality",
33	        expression = "java(toLocality(owner))")
34	    @Mapping(target = "contactPreference",
35	        expression = "java(toContactPreference(owner))")
36	    @Mapping(target = "identityKey",
37	        expression = "java(toIdentityKey(owner))")
38	    @Mapping(target = "checkDigit",
39	        expression = "java(toCheckDigit(owner))")
40	    @Mapping(target = "ageBand",
41	        expression = "java(toAgeBand(owner))")
42	    @Mapping(target = "telephoneDisplay",
43	        expression = "java(toTelephoneDisplay(owner))")
44	    OwnerDto toOwnerDto(Owner owner);
45	
46	    /**
47	     * Derive an owner's age band from the {@code birthDate} relative to the {@code registrationDate}:
48	     * 'MINOR' when under 18, 'ADULT' when 18 to 64, and 'SENIOR' when 65 or older. Returns
49	     * {@code null} when no birth date was supplied (the band is then absent from the DTO). When the
50	     * registration date is missing (e.g. legacy records) the current date is used as the reference.
51	     */
52	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
53	        LocalDate birthDate = owner.getBirthDate();
54	        if (birthDate == null) {
55	            return null;
56	        }
57	        LocalDate reference = owner.getRegistrationDate() != null
58	            ? owner.getRegistrationDate() : LocalDate.now();
59	        int age = Period.between(birthDate, reference).getYears();
60	        if (age < 18) {
61	            return OwnerDto.AgeBandEnum.MINOR;
62	        }
63	        if (age < 65) {
64	            return OwnerDto.AgeBandEnum.ADULT;
65	        }
66	        return OwnerDto.AgeBandEnum.SENIOR;
67	    }
68	
69	    /**
70	     * Format an owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
71	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
72	     * The raw {@code telephone} property is left untouched in E.164 form. Returns the value unchanged
73	     * when it is {@code null} or not in {@code '+'}-prefixed E.164 form.
74	     *
75	     * <p>The recognized dialling codes come from {@link E164PhoneNumbers}, the same table the create
76	     * endpoint validates against, so the two paths cannot diverge. When a number carries no recognized
77	     * code, a two-digit country code is assumed (the most common length).
78	     */
79	    default String toTelephoneDisplay(Owner owner) {
80	        String telephone = owner.getTelephone();
81	        if (telephone == null || !telephone.startsWith("+")) {
82	            return telephone;
83	        }
84	        String digits = telephone.substring(1);
85	        String code = E164PhoneNumbers.countryCode(digits)
86	            .filter(c -> digits.length() > c.length())
87	            .orElse(digits.length() > 2 ? digits.substring(0, 2) : digits);
88	        String national = digits.substring(code.length());
89	        StringBuilder sb = new StringBuilder("+").append(code);
90	        for (int i = 0; i < national.length(); i += 3) {
91	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
92	        }
93	        return sb.toString();
94	    }
95	
96	    /**
97	     * Derive an owner's check digit: a single Luhn check digit (0-9) computed over the digits
98	     * contained in the {@code customerCode}. Non-digit characters (the separators) are ignored.
99	     */
100	    default Integer toCheckDigit(Owner owner) {
101	        String code = owner.getCustomerCode();
102	        if (code == null) {
103	            return null;
104	        }
105	        int sum = 0;
106	        boolean dbl = true;
107	        for (int i = code.length() - 1; i >= 0; i--) {
108	            char c = code.charAt(i);
109	            if (c < '0' || c > '9') {
110	                continue;
111	            }
112	            int d = c - '0';
113	            if (dbl) {
114	                d *= 2;
115	                if (d > 9) {
116	                    d -= 9;
117	                }
118	            }
119	            sum += d;
120	            dbl = !dbl;
121	        }
122	        return (10 - (sum % 10)) % 10;
123	    }
124	
125	    /**
126	     * Derive an owner's duplicate-detection identity key: the normalized E.164 telephone, the
127	     * lower-cased email (empty when none), and the household id (empty when none), joined with
128	     * {@code '|'}. Two owners are duplicates only when their whole identity keys are equal.
129	     *
130	     * <p>This is the single source of truth for the key: it is both returned on the DTO and used by
131	     * the create endpoint's 409 duplicate check, so the value clients see is exactly the value that
132	     * governs rejection. The "email present" rule reuses {@link #hasEmail(Owner)}.
133	     */
134	    default String toIdentityKey(Owner owner) {
135	        String email = hasEmail(owner) ? owner.getEmail() : "";
136	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
137	        return owner.getTelephone() + "|" + email + "|" + household;
138	    }
139	
140	    /**
141	     * Whether the owner has an email address present (non-null and non-empty). Single source of truth
142	     * for the "is an email present" rule shared by the derived fields below.
143	     */
144	    default boolean hasEmail(Owner owner) {
145	        return owner.getEmail() != null && !owner.getEmail().isEmpty();
146	    }
147	
148	    /**
149	     * Derive an owner's preferred contact channel: 'EMAIL' when an email address is present,
150	     * otherwise 'PHONE'.
151	     */
152	    default String toContactPreference(Owner owner) {
153	        return hasEmail(owner) ? "EMAIL" : "PHONE";
154	    }
155	
156	    /**
157	     * Derive an owner's numeric membership level (1 to 3): start at 1; add 1 when an email address is
158	     * present; add 1 when the owner has no namesakes (namesakeCount is 0); capped at 3 (level 4 is
159	     * reserved for tenure).
160	     */
161	    default Integer toMembershipLevel(Owner owner) {
162	        int level = 1;
163	        if (hasEmail(owner)) {
164	            level++;
165	        }
166	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
167	        if (noNamesakes) {
168	            level++;
169	        }
170	        return Math.min(level, 3);
171	    }
172	
173	    /**
174	     * Fixed city-to-region table used as the fall-back when deriving an owner's locality.
175	     */
176	    Map<String, String> CITY_REGION = Map.of(
177	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
178	
179	    /**
180	     * Fixed region-to-inclusive-postcode-range table used to derive an owner's locality from the
181	     * postcode: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}}
182	     * inclusive.
183	     */
